#include "titan_pademu_input_bridge.h"
#include "titan_unified_input.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){TitanPademuTelemetrySnapshot snap;const TitanInputDeviceDescriptor*d;memset(&snap,0,sizeof(snap));snap.version=TITAN_PADEMU_TELEMETRY_VERSION;snap.count=1;snap.pads[0].connected=1;snap.pads[0].port=0;snap.pads[0].device_type=TITAN_PADEMU_DEVICE_DUALSENSE;snap.pads[0].transport=TITAN_PADEMU_TRANSPORT_BT;snap.pads[0].stable_key=0xabc123;snap.pads[0].system_button=1;snap.pads[0].input_valid=1;snap.pads[0].buttons=TITAN_NBTN_CROSS;snap.pads[0].left_x=120;snap.pads[0].left_y=130;snap.pads[0].right_x=140;snap.pads[0].right_y=150;snap.pads[0].battery_state=TITAN_PADEMU_BATTERY_LEVEL;snap.pads[0].battery_percent=70;snap.pads[0].battery_valid=1;TitanUnifiedInput_Initialize();TitanUnifiedInput_SetBootUiActive(1);TitanPademuInputBridge_Initialize();TitanPademuInputBridge_TestSetSnapshot(&snap);assert(TitanPademuInputBridge_SubmitPort(0,1,TITAN_NBTN_CROSS,120,130,140,150));d=TitanUnifiedInput_GetWelcomeCandidate();assert(d&&d->type==TITAN_INPUT_DEVICE_DUALSENSE);assert(d->transport==TITAN_INPUT_TRANSPORT_BLUETOOTH);assert(d->state.buttons&TITAN_NBTN_SYSTEM);assert(d->state.buttons&TITAN_NBTN_CROSS);assert(d->state.left_x==120&&d->state.right_y==150);assert(d->battery_valid&&d->battery_percent==70);assert(TitanUnifiedInput_ClaimPlayerOnFirstInput(d->device_id,0));snap.pads[0].system_button=0;snap.pads[0].buttons=0;snap.pads[0].battery_state=TITAN_PADEMU_BATTERY_UNKNOWN;snap.pads[0].battery_valid=0;TitanUnifiedInput_BeginFrame();TitanPademuInputBridge_TestSetSnapshot(&snap);assert(TitanPademuInputBridge_SubmitPort(0,1,0,128,128,128,128));d=TitanUnifiedInput_GetPlayer(0);assert(d&&!d->battery_valid&&d->battery_state==TITAN_INPUT_BATTERY_UNKNOWN);snap.pads[0].connected=0;TitanPademuInputBridge_TestSetSnapshot(&snap);(void)TitanPademuInputBridge_SubmitPort(0,0,0,128,128,128,128);assert(TitanUnifiedInput_GetPlayer(0)==0);puts("buildfix29-pademu-bridge: OK");return 0;}
